-- =====================================================================
-- Migracao SQLite (Database/BD/dados.db) -> MySQL (curso_ia)
-- Gerado em 2026-09-29
--
-- Compativel com MySQL 5.1+ (charset utf8). Em MySQL >= 5.5.3 pode-se
-- trocar utf8/utf8_general_ci por utf8mb4/utf8mb4_unicode_ci.
--
-- Execucao:
--   mysql -u root -p < curso_ia_mysql.sql
--
-- ATENCAO: as tabelas sao recriadas (DROP TABLE IF EXISTS).
-- =====================================================================

SET NAMES utf8;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS curso_ia
  DEFAULT CHARACTER SET utf8
  DEFAULT COLLATE utf8_general_ci;

USE curso_ia;

-- ---------------------------------------------------------------------
-- Estrutura
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS vendas_itens;
DROP TABLE IF EXISTS vendas;
DROP TABLE IF EXISTS produtos;
DROP TABLE IF EXISTS clientes;

CREATE TABLE clientes (
  Id   INT          NOT NULL AUTO_INCREMENT,
  nome VARCHAR(50)  NOT NULL,
  PRIMARY KEY (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE produtos (
  id       INT            NOT NULL AUTO_INCREMENT,
  nome     VARCHAR(40)    NULL,
  estoque  DECIMAL(15,3)  NULL,
  preco    DECIMAL(15,2)  NULL,
  registro INT            NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE vendas (
  Id         INT            NOT NULL AUTO_INCREMENT,
  id_cliente INT            NOT NULL,
  data       DATE           NULL,
  total      DECIMAL(15,2)  NULL,
  PRIMARY KEY (Id),
  KEY idx_vendas_id_cliente (id_cliente),
  KEY idx_vendas_data (data),
  CONSTRAINT fk_vendas_clientes FOREIGN KEY (id_cliente) REFERENCES clientes (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE vendas_itens (
  id             INT            NOT NULL AUTO_INCREMENT,
  id_venda       INT            NOT NULL,
  id_produto     INT            NOT NULL,
  quantidade     DECIMAL(15,3)  NULL,
  valor_unitario DECIMAL(15,2)  NULL,
  total          DECIMAL(15,2)  NULL,
  PRIMARY KEY (id),
  KEY idx_vendas_itens_id_venda (id_venda),
  KEY idx_vendas_itens_id_produto (id_produto),
  CONSTRAINT fk_vendas_itens_vendas FOREIGN KEY (id_venda) REFERENCES vendas (Id) ON DELETE CASCADE,
  CONSTRAINT fk_vendas_itens_produtos FOREIGN KEY (id_produto) REFERENCES produtos (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ---------------------------------------------------------------------
-- Dados
-- ---------------------------------------------------------------------
START TRANSACTION;

-- clientes: 33 registros

-- produtos: 53 registros

-- vendas: 300 registros

-- vendas_itens: 6774 registros














COMMIT;

-- Mantem a mesma sequencia do SQLite (sqlite_sequence)
ALTER TABLE clientes AUTO_INCREMENT = 34;
ALTER TABLE produtos AUTO_INCREMENT = 70;
ALTER TABLE vendas AUTO_INCREMENT = 901;
ALTER TABLE vendas_itens AUTO_INCREMENT = 6775;

SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- Conferencia (esperado: clientes=33, produtos=53, vendas=300, vendas_itens=6774)
-- ---------------------------------------------------------------------
SELECT 'clientes' AS tabela, COUNT(*) AS registros FROM clientes
UNION ALL SELECT 'produtos', COUNT(*) FROM produtos
UNION ALL SELECT 'vendas', COUNT(*) FROM vendas
UNION ALL SELECT 'vendas_itens', COUNT(*) FROM vendas_itens;
